svg.script:
function updatePipette(volume, liquidColor) {
  // Validate volume (0-10 mL)
  const clampedVolume = Math.max(0, Math.min(10, volume));

  // Select pipette liquid and volume text elements
  const liquidElement = document.getElementById('pipette-liquid');
  const volumeText = document.getElementById('volume-text');

  // Calculate liquid height based on volume (inverse scale)
  const liquidHeight = (clampedVolume / 10) * 40;

  // Update liquid properties
  liquidElement.setAttribute('height', liquidHeight);
  liquidElement.setAttribute('fill', liquidColor);

  // Update volume text
  volumeText.textContent = `${clampedVolume.toFixed(1)} mL`;
}

function drawLiquid(volume, liquidColor) {
  // Simulate drawing liquid into the pipette
  updatePipette(volume, liquidColor);

  // Optional: Add drawing animation or sound effect
  console.log(`Drawing ${volume} mL of ${liquidColor} liquid`);
}

function dispenseLiquid() {
  // Simulate dispensing liquid from the pipette
  const liquidElement = document.getElementById('pipette-liquid');
  const volumeText = document.getElementById('volume-text');

  liquidElement.setAttribute('height', '0');
  volumeText.textContent = '0.0 mL';

  console.log('Liquid dispensed');
}
